using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GiacomoLeopardi
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Aprimi quella finestra... fammi veder la luce.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Credere una cosa perché si è udito dirla, e perché non si è avuta cura di esaminarla, fa torto all'intelletto dell'uomo.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "La condizione progressiva della società non mi riguarda affatto. La mia, se non è retrograda, è eminentemente stazionaria.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Piangi, che ben hai donde, Italia mia.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "L'armi, qua l'armi: io solo combatterò, procomberò sol io. Dammi, o ciel, che sia foco agl'italici petti il sangue mio.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Italo ardito, a che giammai non posi di svegliar dalle tombe i nostri padri? ed a parlar gli meni a questo secol morto, al quale incombe tanta nebbia di tedio?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ahi ahi, ma conosciuto il mondo non cresce, anzi scema, e assai più vasto l'etra sonante e l'alma terra e il mare al fanciullin, che non al saggio appare.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Amore, amor, di nostra vita ultimo inganno, t'abbandonava. Ombra reale e salda ti parve il nulla, e il mondo inabitata piaggia.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Virtù viva sprezziam, lodiamo estinta.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Donna, da voi non poco la patria aspetta", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ad atti egregi è sprone amor, chi ben l'estima, e d'alto affetto maestra è la beltà.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Arcano è tutto, fuor che il nostro dolor.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Negletta prole nascemmo al pianto, e la ragione in grembo de' celesti si posa.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Virtù non luce in disadorno ammanto.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Vivi felice, se felice in terra visse nato mortal.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Tornami a mente il dì che la battaglia d'amore sentii la prima volta, e dissi: oimè, se quest'è amor, com'ei travaglia!", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "D'in su la vetta della torre antica, passero solitario, alla campagna cantando vai finché non more il giorno; ed erra l'armonia per questa valle.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Tu, solingo augellin, venuto a sera del viver che daranno a te le stelle, certo del tuo costume non ti dorrai; ché di natura è frutto ogni vostra vaghezza.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Sempre caro mi fu quest'ermo colle, e questa siepe, che da tanta parte dell'ultimo orizzonte il guardo esclude.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ma, sedendo e mirando, interminati spazi di là da quella, e sovrumani silenzi, e profondissima quiete io nel pensier mi fingo; ove per poco il cor non si spaura.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Così tra questa immensità s'annega il pensier mio; e il naufragar m'è dolce in questo mare.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Dolce e chiara è la notte e senza vento.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ecco è fuggito il dì festivo, ed al festivo il giorno volgar succede, e se ne porta il tempo ogni umano accidente.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Oh come grato occorre nel tempo giovanil, quando ancor lungo la speme e breve ha la memoria il corso, il rimembrar delle passate cose, ancor che triste, e che l'affanno duri!", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Due cose belle ha il mondo: amore e morte.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ma non è cosa in terra che ti somigli; e s'anco pari alcuna ti fosse al volto, agli atti, alla favella, saria, così conforme, assai men bella.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Silvia, rimembri ancora quel tempo della tua vita mortale, quando beltà splendea negli occhi tuoi ridenti e fuggitivi, e tu, lieta e pensosa, il limitare di gioventù salivi?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Io, gli studi leggiadri talor lasciando e le sudate carte, ove il tempo mio primo e di me si spendea la miglior parte,", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "O natura, o natura perché non rendi poi quel che prometti allor? Perché di tanto inganni i figli tuoi?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "All'apparir del vero tu, misera, cadesti: e con la mano la fredda morte ed una tomba ignuda mostravi di lontano.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "dolce per sé; ma con dolor sottentra il pensier del presente, un van desio del passato", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "O speranze, speranze; ameni inganni della mia prima età!", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Che fai tu, luna, in ciel? Dimmi, che fai, silenziosa luna?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Nasce l'uomo a fatica, ed è rischio di morte il nascimento. Prova pena e tormento per prima cosa; e in sul principio stesso la madre e il genitore il prende a consolar dell'esser nato.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Perché reggere in vita chi poi di quella consolar convenga? Se la vita è sventura, perché da noi si dura?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Che sia questo morir, questo supremo scolorar del sembiante, e perir della terra, e venir meno ad ogni usata, amante compagnia.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "E tu certo comprendi il perché delle cose, e vedi il frutto del mattin, della sera, del tacito, infinito andar del tempo.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "A me la vita è male.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Dimmi: perché giacendo a bell'agio, ozioso, s'appaga ogni animale; me, s'io giaccio in riposo, il tedio assale?", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Forse s'avess'io l'ale da volar su le nubi, e noverar le stelle ad una ad una, o come il tuono errar di giogo in giogo, più felice sarei, dolce mia greggia, più felice sarei, candida luna.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "forse, in qual forma, in quale stato che sia, dentro covile o cuna, è funesto a chi nasce il dì natale.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ecco il sereno rompe là da ponente, alla montagna: sgombrasi la campagna, e chiaro nella valle il fiume appare.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Piacer figlio d'affanno;", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Umana prole cara agli eterni! assai felice se respirar ti lice d'alcun dolor: beata se te d'ogni dolor morte risana.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Questo di sette è il più gradito giorno, pien di speme e di gioia: diman tristezza e noia recheran l'ore, ed al travaglio usato ciascuno in suo pensier farà ritorno.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Sempre i codardi, e l'alme ingenerose, abbiette ebbi in dispregio.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Di questa età superba, che di vote speranze si nutrica, vaga di ciance, e di virtù nemica; stolta, che l'util chiede, e inutile la vita quindi più sempre divenir non vede; maggior mi sento.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Pregio non ha, non ha ragion la vita se non per lui, per lui ch'all'uomo è tutto.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Angelica beltade! Parmi ogni più bel volto, ovunque io miro, quasi una finta imago il tuo volto imitar. Tu sola fonte d'ogni altra leggiadria, sola vera beltà parmi che sia.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Fratelli, a un tempo stesso, Amore e Morte ingenerò la sorte. Cose quaggiù sì belle Altre il mondo non ha, non han le stelle.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Poi, quando tutto avvolge la formidabil possa, e fulmina nel cor l'invitta cura, quante volte implorata con desiderio intenso, morte, sei tu dall'affannoso amante!", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Amaro e noia la vita, altro mai nulla; e fango è il mondo.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "l'infinita vanità del tutto.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Torna dinanzi al mio pensier talora il tuo sembiante, Aspasia.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Raggio divino al mio pensiero apparve, donna, la tua beltà. Simile effetto fan la bellezza e i musicali accordi.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Pur quell'ardor che da te nacque è spento: perch'io te non amai, ma quella Diva che già vita, or sepolcro, ha nel mio core.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Già del fato mortale a me bastante e conforto e vendetta è che su l'erba qui neghittoso immobile giacendo, il mar la terra e il ciel miro e sorrido.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Errai, candido Gino; assai gran tempo, e di gran lunga errai. Misera e vana stimai la vita, e sovra l'altre insulsa la stagion ch'or si volge.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "scende la luna; e si scolora il mondo", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Qui su l'arida schiena del formidabil monte sterminator Vesevo, la qual null'altro allegra arbor né fiore, tuoi cespi solitari intorno spargi, odorata ginestra, contenta dei deserti.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Non so se il riso o la pietà prevale.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Così ella vede che il Monti è assai più famoso per l'Iliade che per il Persio.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Certo che non voglio vivere tra la turba: la mediocrità mi fa una paura mortale.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Ho veduto il romanzo del Manzoni, il quale, non ostante molti difetti, mi piace assai, ed è certamente opera di un grande ingegno.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Io non ho bisogno di stima, né di gloria, né di altre cose simili; ma ho bisogno d'amore.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "fare è il miglior modo d'imparare", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "rido della felicità delle masse, perché il mio piccolo cervello non concepisce una massa felice composta d'individui non felici.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Io per me, sapendo che la chiarezza è il primo debito dello scrittore, non ho mai lodata l'avarizia de' segni, e vedo che spesse volte una sola virgola ben messa, dà luce a tutt'un periodo.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Dico che il mondo è una lega di birbanti contro gli uomini dabbene, di vili contro i generosi.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Rari sono i birbanti poveri.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Se la miglior compagnia è quella dalla quale noi partiamo più soddisfatti di noi medesimi, segue ch'ella è appresso a poco quella che noi lasciamo più annoiata.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Nessun maggior segno d'essere poco filosofo e poco savio, che volere savia e filosofica tutta la vita.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Il genere umano e, dal solo individuo in fuori, qualunque minima porzione di esso, si divide in due parti: gli uni usano prepotenza, e gli altri la soffrono.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Nessuna professione è sì sterile come quella delle lettere.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "L'impostura vale e fa effetto anche senza il vero; ma il vero senza lei non può nulla.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Molti vogliono e condursi teco vilmente, e che tu ad un tempo, sotto pena del loro odio, da un lato sii tanto accorto, che tu non dia impedimento alla loro viltà, dall'altro non li conoschi per vili.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Nessuna qualità umana è più intollerabile nella vita ordinaria, né in fatti tollerata meno, che l'intolleranza.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Il mondo [...] non crede mai che chi non cede abbia il torto.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "La schiettezza allora può giovare, quando è usata ad arte, o quando, per la sua rarità, non l'è data fede.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Gli uomini si vergognano non delle ingiurie che fanno, ma di quelle che ricevono.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "La noia non è se non di quelli in cui lo spirito è qualche cosa.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "La stima non è prezzo di ossequi: oltre che essa, non diversa in ciò dall'amicizia, è come un fiore, che pesto una volta gravemente, o appassito, mai più non ritorna.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Rivedendo in capo di qualche anno una persona ch'io avessi conosciuta giovane, sempre alla prima giunta mi è paruto vedere uno che avesse sofferto qualche grande sventura.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Il più certo modo di celare agli altri i confini del proprio sapere, è di non trapassarli.", Author = "Giacomo Leopardi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giacomo_Leopardi", Text = "Le persone non sono ridicole se non quando vogliono parere o essere ciò che non sono.", Author = "Giacomo Leopardi" },
        };
    }
}